function openStudentAppointment(studentId){
 const main=document.querySelector('main');
 main.innerHTML=`<section class="section registration-intro"><p class="eyebrow">CADASTRO APROVADO</p><h1 tabindex="-1">Solicitar atendimento</h1><p class="lead">Escolha o atendimento e informe o dia e horário desejados.</p><div class="form-status">A solicitação só será confirmada quando a secretaria enviar a confirmação por WhatsApp ao aluno ou responsável. Todos os dias e horários podem ser indicados como preferência.</div></section><section class="section registration-layout"><form id="real-appointment"><fieldset><legend>01 · Aluno e contato</legend><div class="form-grid"><label>ID do aluno<input name="studentId" readonly autocomplete="off"></label><label>Nome do solicitante<input name="contactName" required minlength="3" maxlength="120" autocomplete="name"><small>Aluno maior de idade ou responsável pelo aluno.</small></label><label>WhatsApp com DDD<input name="phone" required type="tel" inputmode="tel" maxlength="20" autocomplete="tel"></label></div></fieldset><fieldset><legend>02 · Preferência de atendimento</legend><div class="form-grid"><label>Atendimento<select name="service" required><option value="">Selecione</option><option>Psicologia</option><option>Assistência social</option></select></label><label>Dia da semana<select name="weekday" required><option value="">Selecione</option><option value="0">Domingo</option><option value="1">Segunda-feira</option><option value="2">Terça-feira</option><option value="3">Quarta-feira</option><option value="4">Quinta-feira</option><option value="5">Sexta-feira</option><option value="6">Sábado</option></select></label><label>Data desejada<input name="date" type="date" required></label><label>Horário desejado<input name="time" type="time" required><small>Horário de Brasília.</small></label></div></fieldset><p>O pedido será enviado à secretaria, à coordenação e à profissional escolhida. Os dados pessoais do cadastro, documentos e histórico não são exibidos nesta consulta.</p><label class="consent"><input name="consent" type="checkbox" required>Estou ciente de que estou solicitando atendimento e devo aguardar a confirmação da secretaria por WhatsApp.</label><button class="button" type="submit">Enviar solicitação</button><div id="appointment-result" class="form-status" role="status" tabindex="-1" hidden></div><p><button class="button" type="button" id="change-student">Consultar outro ID</button></p></form></section>`;
 const form=main.querySelector('form'),result=main.querySelector('#appointment-result'),sendButton=form.querySelector('button[type=submit]');
 form.elements.studentId.value=studentId.trim().toUpperCase();
 const profile=document.createElement('p'),profileLink=document.createElement('a');profileLink.href='/portal/#schedule-area';profileLink.textContent='Entrar na área protegida e escolher um horário disponível';profile.append(profileLink);form.before(profile);
 const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
 form.elements.date.min=`${parts.year}-${parts.month}-${parts.day}`;
 let requestId=crypto.randomUUID(),sent=false;
 form.addEventListener('input',()=>{if(!sent){requestId=crypto.randomUUID();result.hidden=true;form.elements.date.setCustomValidity('');form.elements.phone.setCustomValidity('')}});
 form.elements.date.addEventListener('change',()=>{if(form.elements.date.value)form.elements.weekday.value=String(new Date(form.elements.date.value+'T12:00:00Z').getUTCDay())});
 main.querySelector('#change-student').addEventListener('click',()=>location.reload());
 form.addEventListener('submit',async event=>{
  event.preventDefault();if(sent)return;
  const v=Object.fromEntries(new FormData(form));
  form.elements.phone.setCustomValidity(/^\d{10,11}$/.test(v.phone.replace(/\D/g,''))?'':'Informe o WhatsApp com DDD, com 10 ou 11 dígitos.');
  form.elements.date.setCustomValidity(new Date(v.date+'T12:00:00Z').getUTCDay()===Number(v.weekday)?'':'A data precisa corresponder ao dia da semana escolhido.');
  if(!form.reportValidity())return;
  sendButton.disabled=true;sendButton.textContent='Enviando…';result.hidden=true;
  try{const response=await fetch('/api/agenda',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...v,studentId:studentId.trim().toUpperCase(),consent:form.elements.consent.checked,requestId})});const data=await response.json();result.textContent=data.message||'Não foi possível enviar. Tente novamente.';if(response.ok){sent=true;result.textContent+=` Protocolo: ${data.protocol}`;form.querySelectorAll('input,select').forEach(e=>e.disabled=true)}}catch{result.textContent='Não foi possível confirmar o envio. Tente novamente.'}finally{sendButton.disabled=sent;sendButton.textContent=sent?'Solicitação enviada':'Enviar solicitação';result.hidden=false;result.focus()}
 });
 main.querySelector('h1').focus();
}
if(location.pathname.replace(/\/+$/,'')==='/agendamento'){
 document.title='Central de agendamento — Luta pela Comunidade';
 document.querySelector('main').innerHTML=`<section class="section registration-intro"><p class="eyebrow">ACOMPANHAMENTO DO ALUNO</p><h1>Central de agendamento</h1><p><a class="button" href="/portal/#schedule-area">Entrar e ver horários disponíveis</a></p><p>Use o email habilitado no cadastro. Na área protegida você encontra o nome do aluno, os documentos e os horários publicados pelos profissionais.</p><p class="lead">Atendimento com a assistência social e a psicóloga, exclusivo para alunos aprovados no projeto.</p></section><section class="section registration-layout"><div><div class="form-status">A consulta de ID está disponível. Informe o código recebido da coordenação para verificar seu cadastro. A secretaria deverá conferir o responsável; o atendimento só estará confirmado após o WhatsApp da secretaria ao aluno ou responsável.</div><form id="student-scheduling"><fieldset><legend>01 · Identificação do aluno</legend><div class="form-grid"><label>ID do aluno<input id="scheduling-student-id" name="studentId" required maxlength="64" autocomplete="off" spellcheck="false" autocapitalize="characters" aria-describedby="student-id-help student-id-confidentiality"><small id="student-id-help">Digite o ID fornecido pela coordenação após a aprovação da inscrição.</small></label></div><div class="privacy-note" id="student-id-confidentiality"><h3>Seu ID é confidencial</h3><p>O ID é de uso exclusivo do aluno e de seu responsável legal. Não é permitida sua divulgação a terceiros, em redes sociais, grupos ou publicações. Compartilhe-o apenas com a equipe autorizada do projeto, quando necessário para o atendimento.</p><p>O ID aprovado permite solicitar um horário. A secretaria confere a identidade do responsável antes de confirmar o atendimento. Se o ID tiver sido divulgado, comunique a coordenação.</p></div></fieldset><button class="button" type="submit">Verificar acesso</button><div id="scheduling-access-status" role="status" tabindex="-1" hidden></div><p><a class="text-link" href="/inscricao/">Ainda não tenho ID — quero me inscrever</a></p></form></div><aside class="registration-aside"><p class="eyebrow">PASSO A PASSO</p><h2>Cuidado em cada etapa.</h2><ol><li>Inscrição do aluno pelo responsável.</li><li>Conferência dos documentos e aprovação.</li><li>Recebimento confidencial do ID.</li><li>Confirmação de acesso pelo responsável.</li><li>Solicitação do atendimento e do horário desejado.</li><li>Confirmação pela secretaria, por WhatsApp ao aluno ou responsável.</li></ol><p>Seu histórico e seus documentos não são exibidos nesta página.</p><a href="/inscricao/" class="text-link">Realizar inscrição</a></aside></section>`;
 const form=document.querySelector('#student-scheduling'),input=document.querySelector('#scheduling-student-id'),status=document.querySelector('#scheduling-access-status');
 input.addEventListener('input',()=>{input.setCustomValidity('');status.hidden=true;status.textContent=''});
 // The server checks the private registry. ID lookup is not authentication or a reservation.
 const submit=form.querySelector('button[type=submit]');
 form.addEventListener('submit',async e=>{e.preventDefault();input.setCustomValidity(input.value.trim()?'':'Digite o ID fornecido pela coordenação.');if(!form.reportValidity())return;const studentId=input.value.trim();submit.disabled=true;submit.textContent='Consultando cadastro…';status.hidden=true;status.replaceChildren();try{const response=await fetch('/api/student-access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId})});const data=await response.json();status.textContent=data.message||'Não foi possível consultar o cadastro. Tente novamente.';if(response.ok&&data.verified===true){openStudentAppointment(studentId);return}if(response.ok&&data.training===true){window.dispatchEvent(new Event('lpc:training-access'));return}}catch{status.textContent='Não foi possível conectar à consulta. Tente novamente.'}finally{input.value='';submit.disabled=false;submit.textContent='Verificar acesso';status.className='form-status';status.hidden=false;status.focus()}});
}



